import subprocess
import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError("Commands file not found")
    os.makedirs(output_dir_path, exist_ok=True)
    output_files = []
    with open(commands_file_path, 'r') as file:
        reader = csv.reader(file)
        for idx, row in enumerate(reader):
            if not row:
                continue
            cmd = row[0].strip()
            if not cmd:
                continue
            try:
                result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)
                output_content = result.stdout
                if result.returncode != 0:
                    output_content = f"Command failed with exit code {result.returncode}:\n{result.stderr}"
            except subprocess.TimeoutExpired:
                output_content = "Command timed out after 30 seconds."
            except Exception as e:
                output_content = f"Error executing command: {e}"
            output_file_path = os.path.join(output_dir_path, f'command_{idx}_output.txt')
            with open(output_file_path, 'w') as out_file:
                out_file.write(output_content)
            output_files.append(output_file_path)
    return output_files

