import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise ValueError("Invalid script path")
    proc = subprocess.Popen(['bash', script_path], shell=True)
    cpu_total = 0.0
    mem_total = 0
    start_time = time.time()
    while proc.poll() is None and (time.time() - start_time) < timeout:
        try:
            p = psutil.Process(proc.pid)
            cpu_total += p.cpu_percent(interval=0.1)
            mem_info = p.memory_info()
            if mem_info.rss > mem_total:
                mem_total = mem_info.rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        time.sleep(0.1)
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    return {'CPU Usage': cpu_total, 'Memory Usage': mem_total}

