import sys
import subprocess
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    try:
        subprocess.run(['update-alternatives', '--set', 'python', f'/usr/bin/python{python_version}'], shell=True, check=True)
    except subprocess.CalledProcessError:
        try:
            subprocess.run(['pyenv', 'global', python_version], shell=True, check=True)
        except subprocess.CalledProcessError:
            return None
    if path_to_append not in sys.path:
        sys.path.append(path_to_append)
    result = subprocess.run(['python', '--version'], stdout=subprocess.PIPE, shell=True)
    current_version = result.stdout.decode('utf-8').strip()
    return current_version
